function room(id,name,parent,art,loot){const m=map(id,name,'interior',[exit(id+'-exit',11,15,'밖으로',parent),entity(id+'-food','loot',7,7,'먹거리',{art,loot}),entity(id+'-rest','rest',14,9,'쉬는 자리',{art:'rock'})]);m.obstacles=m.obstacles.filter(o=>o.x===0||o.x===23||o.y===0||o.y===17).map(o=>({...o,art:'rock'}));return m;}
paleolithic.maps.push(room('paleo-shelter','막집 안','paleo-camp','rawmeat',{rawmeat:2,berries:2}),room('paleo-cave','불빛 동굴','paleo-camp','fish',{fish:2}));
paleolithic.maps.at(-1).entities.push(relic('fire',11,5,'불의 사용','campfire'),person('paleo-cold',17,11,'추위에 떠는 사람',['밤에는 너무 추워.'],'farmer',{request:'paleo-hide'}));
bronze.maps.push(room('bronze-room','큰 집 안','bronze-village','grain',{millet:2,barnyard:1}));

export const QUIZZES={nation:{question:'우리나라의 첫 나라는?',options:['고조선','고구려','고려'],answer:0,xp:0,coins:0},'bronze-rice':{intro:'농사를 짓고 나니 먹을 것이 예전보다 많이 남기 시작했어.\n먹을 것을 많이 가진 사람과 그렇지 않은 사람 사이에 차이도 생겼지.',question:'청동기 시대에 중요해진 이것은 무엇일까?',options:['벼','밀','과일'],answer:0,xp:15,coins:0,wrongCoins:3,storyEvent:'quiz:bronze-rice'},samhan:{question:'삼한을 이루는 세 한은 무엇일까?',options:['마한 · 변한 · 진한','부여 · 옥저 · 동예','부여 · 고구려 · 삼한'],answer:0,xp:0,coins:0,storyEvent:'quiz:samhan'},stone:{question:'구석기 사람들이 사용한 도구는?',options:['비파형 동검','주먹도끼','측우기'],answer:1,xp:15,coins:15},pot:{question:'신석기 시대의 대표 토기는?',options:['고려청자','백자','빗살무늬 토기'],answer:2,xp:15,coins:15},grain:{question:'농업 발달로 먹고도 남게 된 것은?',options:['자동차','잉여 생산물','공장'],answer:1,xp:15,coins:15}};

export function expand(pre,go){for(const r of [pre,go])for(const m of r.maps)for(const e of m.entities)if(e.type==='npc'&&e.art==='researcher')e.art='farmer';pre.name='신석기 시대';pre.subtitle='농경과 정착 생활';pre.unlock='bronze';pre.artifacts=pre.artifacts.filter(a=>a.id!=='handaxe');pre.quests[1]={...pre.quests[1],title:'가락바퀴를 찾자.',detail:'마을의 움집 주변을 살펴보자.',map:'pre-village',target:'spindle',event:'artifact:spindle'};pre.quests[4].title='동굴의 돌도구를 살펴보자.';pre.quests[5]={...pre.quests[5],title:'빛나는 청동기를 조사하자.',map:'pre-cave',target:'bronze-tool',event:'artifact:bronze-tool'};pre.maps.find(m=>m.id==='pre-forest').entities=pre.maps.find(m=>m.id==='pre-forest').entities.filter(e=>e.artifact!=='handaxe');pre.maps.find(m=>m.id==='pre-cave').entities.push(relic('bronze-tool',15,5,'청동기','mirror'));const elder=pre.maps[0].entities.find(e=>e.id==='pre-elder');elder.lines=['이곳에서는 농경과 목축을 시작했어.\n사냥과 고기잡이도 계속하고 있지.','토기와 돌낫을 찾아보자.\n실을 만드는 도구도 있어.'];pre.maps[0].entities.find(e=>e.id==='pottery').x=7;const hut=pre.maps[0].entities.find(e=>e.id==='pre-hut1');Object.assign(hut,{type:'house',to:'neo-room'});pre.maps.push(room('neo-room','움집 안','pre-village','grain',{millet:2,fish:1,food:1}));pre.shop.push('rawmeat','fish','cookedfish','millet','barnyard','sorghum');go.quests[3]={...go.quests[3],title:'마을 사람들이 모이는 자리를 살펴보자.',target:'go-council',event:'inspect:go-council'};go.maps.find(m=>m.id==='go-dolmen').entities.push(entity('go-council','inspect',8,10,'마을의 모임터',{art:'campfire',lines:['여러 마을의 일을 함께 정했다.\n사람마다 맡은 일이 달라졌다.']}));go.artifacts=go.artifacts.filter(a=>a.id!=='dolmen');Object.assign(go.maps[0].entities.find(e=>e.id==='go-hut1'),{type:'house',to:'go-room'});go.maps.push(room('go-room','마을 집 안','go-village','rice',{rice:2,food:1}));go.shop.push('fish','cookedfish','millet','barnyard','sorghum','ricecrop','rice');go.maps[0].entities.push(...[['stone',7,6,'돌도구 선생님'],['pot',18,7,'토기 선생님'],['grain',9,12,'곡식 선생님']].map(([quiz,x,y,name])=>entity('quiz-'+quiz,'quiz',x,y,name,{art:'elder',quiz})));for(const r of [pre,go])for(const q of r.quests){q.xp=Math.floor(q.xp*.8);q.coins=Math.floor(q.coins*.8);}for(const r of [paleolithic,pre])for(const m of r.maps)for(const e of m.entities)if(e.type==='chest'){e.type='loot';e.loot={food:1,fish:1};e.art='meat';e.name='남겨진 음식';}}
